#!/bin/sh
# 段布局与体积：.bss 只记录长度，不占文件空间
# 期望输出见 expected_output（本机 MinGW 工具链真实执行捕获）

cat > big.c << 'EOF'
#include <stdio.h>
#include <string.h>

char big_bss[1 << 20];              /* 1 MiB 未初始化：进 .bss */
char big_data[1024] = { 1 };        /* 已初始化（非零）：进 .data */
static const char msg[] = "sections";   /* 只读：进 .rodata */

int main(void)
{
    big_bss[0] = 'x';
    printf("%s: bss[0]=%c data[0]=%d\n", msg, big_bss[0], big_data[0]);
    return 0;
}
EOF

gcc -c big.c -o big.o
objdump -h big.o      # 看 .bss 的 size 与段属性
size big.o            # text/data/bss 三段字节数
gcc big.o -o big.exe
size big.exe          # bss 约 1 MiB，但文件本身很小
./big
